// Merge Sort a Vector
#include <iostream>
#include <vector>
using namespace std;

void merge_ranges(vector<int> &v, int lo, int mid, int hi) {
    vector<int> t;
    int i = lo, j = mid;
    while (i < mid && j < hi)
        t.push_back(v[i] <= v[j] ? v[i++] : v[j++]);
    while (i < mid) t.push_back(v[i++]);
    while (j < hi) t.push_back(v[j++]);
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
}

void msort_rec(vector<int> &v, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    msort_rec(v, lo, mid);
    msort_rec(v, mid, hi);
    merge_ranges(v, lo, mid, hi);
}

vector<int> merge_sort(vector<int> v) {
    msort_rec(v, 0, (int)v.size());
    return v;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    vector<int> res = merge_sort(v);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Quicksort a Vector (Lomuto, last element as pivot)
#include <iostream>
#include <vector>
using namespace std;

int qsort_partition(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

void qsort_rec(vector<int> &v, int lo, int hi) {
    if (lo >= hi) return;
    int p = qsort_partition(v, lo, hi);
    qsort_rec(v, lo, p - 1);
    qsort_rec(v, p + 1, hi);
}

vector<int> quick_sort(vector<int> v) {
    qsort_rec(v, 0, (int)v.size() - 1);
    return v;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
