// Merge Steps in Merge Sort (one step per element written into the temp)
#include <iostream>
#include <vector>
using namespace std;

void merge_count(vector<int> &v, int lo, int mid, int hi, long long &steps) {
    vector<int> t;
    int i = lo, j = mid;
    while (i < mid && j < hi) {
        if (v[i] <= v[j]) {
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
        }
        steps++;
    }
    while (i < mid) {
        t.push_back(v[i]);
        i++;
        steps++;
    }
    while (j < hi) {
        t.push_back(v[j]);
        j++;
        steps++;
    }
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
}

void msort_count_rec(vector<int> &v, int lo, int hi, long long &steps) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    msort_count_rec(v, lo, mid, steps);
    msort_count_rec(v, mid, hi, steps);
    merge_count(v, lo, mid, hi, steps);
}

void merge_sort_count(vector<int> &v, long long &steps) {
    steps = 0;
    msort_count_rec(v, 0, (int)v.size(), steps);
}

