// Kth Smallest Ticket Number (quickselect, Lomuto, last element as pivot)
#include <iostream>
#include <vector>
using namespace std;

int lomuto_pick(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

int kth_smallest(vector<int> v, int k) {
    int lo = 0, hi = (int)v.size() - 1;
    while (true) {
        int p = lomuto_pick(v, lo, hi);
        if (p == k - 1) return v[p];
        if (p < k - 1) lo = p + 1;
        else hi = p - 1;
    }
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    int k;
    cin >> k;
    cout << kth_smallest(v, k) << "\n";
    return 0;
}

// Three-Way Partition of Mail (stable around the given pivot)
#include <iostream>
#include <vector>
using namespace std;

void three_way_partition(vector<int> &v, int pivot) {
    vector<int> less, equal, greater;
    for (int x : v) {
        if (x < pivot) less.push_back(x);
        else if (x == pivot) equal.push_back(x);
        else greater.push_back(x);
    }
    int i = 0;
    for (int x : less) v[i++] = x;
    for (int x : equal) v[i++] = x;
    for (int x : greater) v[i++] = x;
}

