// Merge Comparisons in Merge Sort (each "left <= right" test is one)
#include <iostream>
#include <vector>
using namespace std;

void merge_comp(vector<int> &v, int lo, int mid, int hi, long long &comparisons) {
    vector<int> t;
    int i = lo, j = mid;
    while (i < mid && j < hi) {
        comparisons++;
        if (v[i] <= v[j]) {
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
        }
    }
    while (i < mid) {
        t.push_back(v[i]);
        i++;
    }
    while (j < hi) {
        t.push_back(v[j]);
        j++;
    }
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
}

void msort_comp_rec(vector<int> &v, int lo, int hi, long long &comparisons) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    msort_comp_rec(v, lo, mid, comparisons);
    msort_comp_rec(v, mid, hi, comparisons);
    merge_comp(v, lo, mid, hi, comparisons);
}

void merge_sort_comp(vector<int> &v, long long &comparisons) {
    comparisons = 0;
    msort_comp_rec(v, 0, (int)v.size(), comparisons);
}

