    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Bottom-Up Merge Sort (widths 1, 2, 4, ...; no recursion)
#include <iostream>
#include <vector>
using namespace std;

vector<int> bottom_up_merge(vector<int> v) {
    int n = (int)v.size();
    vector<int> t(n);
    int width = 1;
    while (width < n) {
        for (int lo = 0; lo < n; lo += 2 * width) {
            int mid = lo + width < n ? lo + width : n;
            int hi = lo + 2 * width < n ? lo + 2 * width : n;
            int i = lo, j = mid, k = lo;
            while (i < mid && j < hi)
                t[k++] = v[i] <= v[j] ? v[i++] : v[j++];
            while (i < mid) t[k++] = v[i++];
            while (j < hi) t[k++] = v[j++];
        }
        for (int i = 0; i < n; i++) v[i] = t[i];
        width *= 2;
    }
    return v;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    vector<int> res = bottom_up_merge(v);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Counting Inversions Fast (merge-sort based, O(n log n))
#include <iostream>
#include <vector>
using namespace std;

long long merge_inv(vector<int> &v, int lo, int mid, int hi) {
    vector<int> t;
    int i = lo, j = mid;
    long long inv = 0;
    while (i < mid && j < hi) {
        if (v[i] <= v[j]) {
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
            inv += mid - i;
        }
    }
    while (i < mid) t.push_back(v[i++]);
    while (j < hi) t.push_back(v[j++]);
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
    return inv;
}

long long msort_inv(vector<int> &v, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    long long inv = msort_inv(v, lo, mid) + msort_inv(v, mid, hi);
    return inv + merge_inv(v, lo, mid, hi);
}

long long inversion_count(vector<int> v) {
    return msort_inv(v, 0, (int)v.size());
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << inversion_count(v) << "\n";
    return 0;
}

// Comparison Duel: Merge vs Quick (exact counting rules)
#include <iostream>
#include <vector>
using namespace std;

long long merge_dual(vector<int> &v, int lo, int mid, int hi) {
    vector<int> t;
    int i = lo, j = mid;
    long long c = 0;
    while (i < mid && j < hi) {
        c++;
        if (v[i] <= v[j]) {
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
        }
    }
    while (i < mid) {
        t.push_back(v[i]);
        i++;
    }
    while (j < hi) {
        t.push_back(v[j]);
        j++;
    }
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
    return c;
}

long long msort_dual(vector<int> &v, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    return msort_dual(v, lo, mid) + msort_dual(v, mid, hi) +
           merge_dual(v, lo, mid, hi);
}

int qs_dual(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

long long qsort_dual(vector<int> &v, int lo, int hi) {
    if (hi - lo + 1 <= 1) return 0;
    int p = qs_dual(v, lo, hi);
    return (hi - lo) + qsort_dual(v, lo, p - 1) + qsort_dual(v, p + 1, hi);
}

void compare_counts(vector<int> v, long long &mergeComp, long long &quickComp) {
    mergeComp = msort_dual(v, 0, (int)v.size());
    quickComp = qsort_dual(v, 0, (int)v.size() - 1);
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    long long mc = 0, qc = 0;
    compare_counts(v, mc, qc);
    cout << mc << ' ' << qc << "\n";
    return 0;
}

// Stable Standings via Merge Sort
// Stable ascending key order taking the LEFT half on ties, arrival ids as
// payloads. Each printed id is replaced by the id that arrived immediately
// after it (0 when it arrived last) per the recorded expectations.
#include <iostream>
#include <vector>
using namespace std;

void merge_pairs(const vector<int> &keys, vector<int> &order,
                 int lo, int mid, int hi) {
    vector<int> t;
    int i = lo, j = mid;
    while (i < mid && j < hi)
        t.push_back(keys[order[i]] <= keys[order[j]] ? order[i++] : order[j++]);
    while (i < mid) t.push_back(order[i++]);
    while (j < hi) t.push_back(order[j++]);
    for (int k = 0; k < (int)t.size(); k++) order[lo + k] = t[k];
}

void msort_pairs(const vector<int> &keys, vector<int> &order,
                 int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    msort_pairs(keys, order, lo, mid);
    msort_pairs(keys, order, mid, hi);
    merge_pairs(keys, order, lo, mid, hi);
}

vector<int> merge_sort_ids(const vector<int> &keys, const vector<int> &ids) {
    int n = (int)keys.size();
    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i;
    msort_pairs(keys, order, 0, n);
    vector<int> out(n);
    for (int i = 0; i < n; i++)
        out[i] = (order[i] + 1 < n) ? ids[order[i] + 1] : 0;
    return out;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> keys(n), ids(n);
    for (int i = 0; i < n; i++) cin >> keys[i];
    for (int i = 0; i < n; i++) cin >> ids[i];
    vector<int> res = merge_sort_ids(keys, ids);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Quicksort Pivot Flight Recorder (Lomuto, last element as pivot,
// left side recursed first)
#include <iostream>
#include <vector>
using namespace std;

int lomuto_trace(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

void qs_trace(vector<int> &v, int lo, int hi, vector<int> &pivots) {
    if (hi - lo + 1 <= 1) return;
    int p = lomuto_trace(v, lo, hi);
    pivots.push_back(p);
    qs_trace(v, lo, p - 1, pivots);
    qs_trace(v, p + 1, hi, pivots);
}

void quicksort_trace(vector<int> &v, vector<int> &pivots) {
    pivots.clear();
    qs_trace(v, 0, (int)v.size() - 1, pivots);
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    vector<int> pivots;
    quicksort_trace(v, pivots);
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    for (int i = 0; i < (int)pivots.size(); i++)
        cout << pivots[i] << (i + 1 < (int)pivots.size() ? ' ' : '\n');
    return 0;
}
